const sidebar: VariantTokenMeta[] = [
  { key: 'sidebar', group: 'sidebar', source: 'scheme', shadeLinked: true, i18n: 'theme.variant.sidebar' },
  { key: 'sidebarForeground', group: 'sidebar', source: 'scheme', i18n: 'theme.variant.sidebarForeground' },
